// ===========================================================================
//  Exact convex-polygon intersection (Sutherland-Hodgman in the lazy exact
//  kernel Epeck)
//
//  Correctness by construction:
//    * Inputs (Epick / double coordinates) convert exactly to Epeck rationals.
//    * Every orientation predicate and every clip-edge intersection is
//      computed in Epeck.  Epeck is lazy: it runs interval-arithmetic filters
//      at ~double speed and escalates to exact rationals only when an interval
//      is ambiguous.  So constructed intersection points are carried EXACTLY
//      into the predicates of subsequent clip edges — there is no per-edge
//      rounding drift, and no "validate the result / discard on failure"
//      step is needed or used.
//    * The result is rounded to double exactly once, when it is handed back to
//      the caller for storage in the recurrence state.
//
//  Sutherland-Hodgman clips the CCW subject polygon against each half-plane of
//  the CCW clip polygon.  A vertex is inside a half-plane iff it is LEFT_TURN
//  or COLLINEAR w.r.t. the clip edge (closed-set semantics: touching contacts
//  are kept, never silently dropped).
// ===========================================================================
namespace exact_geom {

using EPoint = Epeck::Point_2;
using ELine  = Epeck::Line_2;

inline EPoint to_exact(const Point& p) {
    return EPoint(Epeck::FT(CGAL::to_double(p.x())),
                  Epeck::FT(CGAL::to_double(p.y())));
}

inline Point to_inexact(const EPoint& p) {
    return Point(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
}

// Signed area sign of a CCW-candidate polygon, computed exactly.
inline CGAL::Sign signed_area_sign(const std::vector<EPoint>& poly) {
    const int n = (int)poly.size();
    Epeck::FT s = 0;
    for (int i = 0; i < n; ++i) {
        const EPoint& a = poly[i];
        const EPoint& b = poly[(i + 1) % n];
        s += a.x() * b.y() - b.x() * a.y();
    }
    return CGAL::sign(s);
}

// Clip `subject` (CCW) against the half-plane to the left of directed edge a->b.
inline std::vector<EPoint> clip_halfplane(const std::vector<EPoint>& subject,
                                          const EPoint& a, const EPoint& b) {
    const int n = (int)subject.size();
    std::vector<EPoint> out;
    if (n == 0) return out;
    out.reserve(n + 1);

    auto inside = [&](const EPoint& p) {
        // Inside iff not strictly to the right of a->b.
        return CGAL::orientation(a, b, p) != CGAL::RIGHT_TURN;
    };

    EPoint prev = subject[n - 1];
    bool prev_in = inside(prev);
    for (int i = 0; i < n; ++i) {
        const EPoint& cur = subject[i];
        const bool cur_in = inside(cur);
        if (cur_in) {
            if (!prev_in) {
                // Crossing from outside to inside: prev and cur are on strictly
                // opposite sides, so the segment meets the clip line in a point.
                auto res = CGAL::intersection(ELine(a, b), ELine(prev, cur));
                if (res) {
                    if (const EPoint* ip = std::get_if<EPoint>(&*res))
                        out.push_back(*ip);
                }
            }
            out.push_back(cur);
        } else if (prev_in) {
            auto res = CGAL::intersection(ELine(a, b), ELine(prev, cur));
            if (res) {
                if (const EPoint* ip = std::get_if<EPoint>(&*res))
                    out.push_back(*ip);
            }
        }
        prev = cur;
        prev_in = cur_in;
    }
    return out;
}

// Remove exact-duplicate and exactly-collinear vertices (cyclic).  After this,
// a full-dimensional intersection has >= 3 vertices; a segment/point collapses
// to < 3 and is reported as "not full-dimensional" by the public API.
inline void canonicalize(std::vector<EPoint>& poly) {
    // Drop consecutive duplicates (including wrap-around).
    std::vector<EPoint> dedup;
    dedup.reserve(poly.size());
    for (const auto& p : poly) {
        if (dedup.empty() || dedup.back() != p) dedup.push_back(p);
    }
    while (dedup.size() > 1 && dedup.front() == dedup.back()) dedup.pop_back();
    poly.swap(dedup);

    // Iteratively drop vertices collinear with their cyclic neighbours.
    bool changed = true;
    while (changed && poly.size() >= 3) {
        changed = false;
        std::vector<EPoint> keep;
        keep.reserve(poly.size());
        const int n = (int)poly.size();
        for (int i = 0; i < n; ++i) {
            const EPoint& prev = poly[(i - 1 + n) % n];
            const EPoint& cur  = poly[i];
            const EPoint& next = poly[(i + 1) % n];
            if (CGAL::orientation(prev, cur, next) == CGAL::COLLINEAR) {
                changed = true;  // drop cur
            } else {
                keep.push_back(cur);
            }
        }
        poly.swap(keep);
    }
}

}  // namespace exact_geom

// ===========================================================================
//  Intersection (public API)
// ===========================================================================

// Computes the exact intersection of two convex polygons and returns it in
// `result` (CCW, double coordinates).  Returns true iff the intersection is
// full-dimensional (>= 3 non-collinear vertices) — the invariant find_F relies
// on.  A lower-dimensional meet (empty / point / segment) reports false.
inline bool intersect(const std::vector<Point>& P_verts,
                      const std::vector<Point>& Q_verts,
                      std::vector<Point>& result) {
    using namespace exact_geom;
    result.clear();
    if (P_verts.size() < 3 || Q_verts.size() < 3) return false;

    std::vector<EPoint> subject, clip;
    subject.reserve(P_verts.size());
    clip.reserve(Q_verts.size());
    for (const auto& p : P_verts) subject.push_back(to_exact(p));
    for (const auto& q : Q_verts) clip.push_back(to_exact(q));

    // Sutherland-Hodgman requires CCW orientation for the "left = inside" rule.
    if (signed_area_sign(subject) == CGAL::NEGATIVE)
        std::reverse(subject.begin(), subject.end());
    if (signed_area_sign(clip) == CGAL::NEGATIVE)
        std::reverse(clip.begin(), clip.end());

    std::vector<EPoint> running = subject;
    const int m = (int)clip.size();
    for (int e = 0; e < m; ++e) {
        running = clip_halfplane(running, clip[e], clip[(e + 1) % m]);
        if (running.empty()) return false;
    }

    canonicalize(running);
    if (running.size() < 3) return false;

    result.reserve(running.size());
    for (const auto& p : running) result.push_back(to_inexact(p));

    // The exact meet is CCW; guard the single double-rounding step against a
    // sign flip on a near-degenerate vertex.
    if (kernel_signed_area(result) < 0)
        std::reverse(result.begin(), result.end());
    return true;
}

inline bool intersect(const Polygon& subject, const Polygon& clip,
                      std::vector<Point>& result) {
    std::vector<Point> P_verts(subject.vertices_begin(), subject.vertices_end());
    std::vector<Point> Q_verts(clip.vertices_begin(), clip.vertices_end());
    return intersect(P_verts, Q_verts, result);
}

// ===========================================================================
//  Helpers
// ===========================================================================

inline double kernel_signed_area(const std::vector<Point>& P) {
    double s = 0.0;
    int sz = (int)P.size();
    for (int i = 0; i < sz; ++i) {
        const Point& a = P[i];
        const Point& b = P[(i + 1) % sz];
        s += CGAL::to_double(a.x() * b.y() - b.x() * a.y());
    }
    return s / 2.0;
}

// ===========================================================================
