namespace exact_geom {

using EPoint = Epeck::Point_2;
using ELine  = Epeck::Line_2;

// A directed line through two ORIGINAL input points (double coordinates).
struct Seg { double ax, ay, bx, by; };

// A running-polygon vertex.
//   (x, y)  : vertex position in double.  For an original subject vertex this
//             is exact; for a clip crossing it is the double-rounded meet of
//             its two defining lines.
//   os      : the OUTGOING edge's support line (prev-of-next), as ORIGINAL
//             points — this is what the clipper intersects to build the next
//             crossing, so crossings are always meets of ORIGINAL lines.
//   d1, d2  : the two ORIGINAL lines whose intersection IS this vertex.  Used
//             only for the exact fallback / exact canonicalization, so every
//             exact evaluation is a self-contained depth-1 construction — no
//             chained lazy DAG, hence no bit-length blow-up.
//   is_orig : true => exact position is (x, y) directly.
struct Vtx {
    double x, y;
    Seg os;
    Seg d1, d2;
    bool is_orig;
};

inline EPoint to_exact_xy(double x, double y) {
    return EPoint(Epeck::FT(x), Epeck::FT(y));
}

// Exact meet of two ORIGINAL lines (depth-1 construction).  Returns false only
// for parallel/coincident lines (never a genuine crossing).
inline bool exact_meet(const Seg& A, const Seg& B, EPoint& out) {
    ELine la(to_exact_xy(A.ax, A.ay), to_exact_xy(A.bx, A.by));
    ELine lb(to_exact_xy(B.ax, B.ay), to_exact_xy(B.bx, B.by));
    auto res = CGAL::intersection(la, lb);
    if (!res) return false;
    if (const EPoint* ip = std::get_if<EPoint>(&*res)) { out = *ip; return true; }
    return false;
}

// Exact position of a vertex (depth-1: either an original double, or one meet).
inline EPoint exact_pos(const Vtx& v) {
    if (v.is_orig) return to_exact_xy(v.x, v.y);
    EPoint q;
    if (exact_meet(v.d1, v.d2, q)) return q;
    return to_exact_xy(v.x, v.y);  // parallel guard (shouldn't happen)
}

// Double line-line meet for the stored (rounded) crossing position.
inline bool dmeet(const Seg& A, const Seg& B, double& x, double& y) {
    const double r1 = A.bx - A.ax, r2 = A.by - A.ay;
    const double s1 = B.bx - B.ax, s2 = B.by - B.ay;
    const double den = r1 * s2 - r2 * s1;
    if (den == 0.0) return false;
    const double t = ((B.ax - A.ax) * s2 - (B.ay - A.ay) * s1) / den;
    x = A.ax + t * r1;
    y = A.ay + t * r2;
    return true;
}

// Is v inside the half-plane left of directed clip edge (ca -> cb)?
// Filtered: the fast double branch returns the EXACT sign of
// orientation(ca, cb, true_v) whenever |det| exceeds a bound that dominates
// both the double round-off of the determinant AND the ~ulp rounding of the
// stored position; otherwise it escalates to an exact predicate on the
// vertex's exact (depth-1) position.  So the inside/outside decision — which
// drives every topological choice — is mathematically exact.
inline bool inside(double cax, double cay, double cbx, double cby,
                   const Vtx& v) {
    const double ux = cbx - cax, uy = cby - cay;
    const double vx = v.x - cax, vy = v.y - cay;
    const double t1 = ux * vy;
    const double t2 = uy * vx;
    const double det = t1 - t2;
    constexpr double eps = std::numeric_limits<double>::epsilon();
    const double err = 64.0 * eps * (std::abs(t1) + std::abs(t2));
    if (det >  err) return true;   // strictly left  -> inside
    if (det < -err) return false;  // strictly right -> outside
    // Ambiguous: exact predicate on the exact vertex position.
    return CGAL::orientation(to_exact_xy(cax, cay), to_exact_xy(cbx, cby),
                             exact_pos(v)) != CGAL::RIGHT_TURN;
}

// Clip `subject` (CCW) against the half-plane left of directed clip edge
// (ca -> cb), given as ORIGINAL points.
inline std::vector<Vtx> clip_halfplane(const std::vector<Vtx>& subject,
                                       double cax, double cay,
                                       double cbx, double cby) {
    const int n = (int)subject.size();
    std::vector<Vtx> out;
    if (n == 0) return out;
    out.reserve(n + 1);
    const Seg clip_seg{cax, cay, cbx, cby};

    for (int i = 0; i < n; ++i) {
        const Vtx& prev = subject[(i - 1 + n) % n];
        const Vtx& cur  = subject[i];
        const bool prev_in = inside(cax, cay, cbx, cby, prev);
        const bool cur_in  = inside(cax, cay, cbx, cby, cur);

        if (cur_in) {
            if (!prev_in) {
                // Entering across the clip line on edge prev->cur (support
                // prev.os).  Entry vertex continues along that subject edge.
                double qx, qy;
                if (dmeet(clip_seg, prev.os, qx, qy))
                    out.push_back(Vtx{qx, qy, prev.os, clip_seg, prev.os, false});
            }
            out.push_back(cur);
        } else if (prev_in) {
            // Leaving on edge prev->cur; exit vertex's outgoing edge runs along
            // the clip line.
            double qx, qy;
            if (dmeet(clip_seg, prev.os, qx, qy))
                out.push_back(Vtx{qx, qy, clip_seg, clip_seg, prev.os, false});
        }
    }
    return out;
}

// Exact-canonicalize the clipped vertices: drop exact-duplicate and exactly-
// collinear vertices (cyclic), using each vertex's exact depth-1 position.  A
// full-dimensional meet keeps >= 3 vertices; a segment/point collapses to < 3.
inline std::vector<EPoint> canonicalize(const std::vector<Vtx>& verts) {
    std::vector<EPoint> poly;
    poly.reserve(verts.size());
    for (const auto& v : verts) poly.push_back(exact_pos(v));

    std::vector<EPoint> dedup;
    dedup.reserve(poly.size());
    for (const auto& p : poly) {
        if (dedup.empty() || dedup.back() != p) dedup.push_back(p);
    }
    while (dedup.size() > 1 && dedup.front() == dedup.back()) dedup.pop_back();
    poly.swap(dedup);

    bool changed = true;
    while (changed && poly.size() >= 3) {
        changed = false;
        std::vector<EPoint> keep;
        keep.reserve(poly.size());
        const int n = (int)poly.size();
        for (int i = 0; i < n; ++i) {
            const EPoint& prev = poly[(i - 1 + n) % n];
            const EPoint& cur  = poly[i];
            const EPoint& next = poly[(i + 1) % n];
            if (CGAL::orientation(prev, cur, next) == CGAL::COLLINEAR) {
                changed = true;  // drop cur
            } else {
                keep.push_back(cur);
            }
        }
        poly.swap(keep);
    }
    return poly;
}

}  // namespace exact_geom

