#include "simplify_geometry.h"
#include <chrono>
#include <cstdio>
#include <random>

int main() {
    // A ~10-vertex convex "bbox-clipped fan" style subject and a ~10-vertex
    // convex-hull-of-grid style clip, overlapping.
    std::vector<Point> subject = {
        {-5000, -5000}, {5000, -5000}, {5000, 5000}, {-5000, 5000},
    };
    // Build a grid-hull-like clip polygon around origin.
    std::vector<Point> clip;
    const double GRID = 35.0;
    for (int a = 0; a < 12; ++a) {
        double ang = 2.0 * M_PI * a / 12.0;
        double r = 300.0;
        double x = std::round(r * std::cos(ang) / GRID) * GRID;
        double y = std::round(r * std::sin(ang) / GRID) * GRID;
        clip.push_back(Point(x, y));
    }
    std::vector<Point> hull;
    CGAL::convex_hull_2(clip.begin(), clip.end(), std::back_inserter(hull));
    clip = hull;

    std::vector<Point> result;
    const int N = 200000;
    auto t0 = std::chrono::steady_clock::now();
    long long total_verts = 0;
    int hits = 0;
    for (int i = 0; i < N; ++i) {
        bool h = intersect(subject, clip, result);
        if (h) { ++hits; total_verts += (long long)result.size(); }
    }
    auto t1 = std::chrono::steady_clock::now();
    double secs = std::chrono::duration<double>(t1 - t0).count();
    std::printf("N=%d hits=%d avg_verts=%.2f  total=%.4fs  per_call=%.3f us\n",
                N, hits, total_verts / (double)std::max(1, hits),
                secs, secs / N * 1e6);
    return 0;
}

