#include "simplify_geometry.h"
#include <chrono>
#include <cstdio>
#include <random>
#include <vector>

// Build a regular convex polygon (CCW) of `k` vertices, radius r, centre (cx,cy).
static std::vector<Point> regular_poly(int k, double r, double cx, double cy,
                                       double phase) {
    std::vector<Point> v;
    v.reserve(k);
    for (int i = 0; i < k; ++i) {
        double a = phase + 2.0 * M_PI * i / k;
        v.emplace_back(cx + r * std::cos(a), cy + r * std::sin(a));
    }
    return v;
}

int main(int argc, char** argv) {
    const int N = (argc > 1) ? std::atoi(argv[1]) : 86491;

    // Representative sizes from the profile: F ~ up to ~12, G ~ 8-12.
    std::mt19937 rng(12345);
    std::uniform_real_distribution<double> off(-150.0, 150.0);
    std::uniform_int_distribution<int> ksub(6, 12), kclip(6, 12);

    // Pre-generate a pool of overlapping polygon pairs at realistic coords.
    const int POOL = 512;
    std::vector<std::vector<Point>> Ps(POOL), Qs(POOL);
    for (int i = 0; i < POOL; ++i) {
        double cx = 5000 + off(rng), cy = 5000 + off(rng);
        Ps[i] = regular_poly(ksub(rng), 200.0, cx, cy, 0.1 * i);
        Qs[i] = regular_poly(kclip(rng), 180.0, cx + off(rng), cy + off(rng),
                             0.07 * i);
    }

    std::vector<Point> result;
    long long ok = 0;
    auto t0 = std::chrono::steady_clock::now();
    for (int i = 0; i < N; ++i) {
        const auto& P = Ps[i % POOL];
        const auto& Q = Qs[i % POOL];
        if (intersect(P, Q, result)) ok += result.size();
    }
    auto t1 = std::chrono::steady_clock::now();
    double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
    std::printf("N=%d  total=%.2f ms  per-call=%.3f us  checksum=%lld\n",
                N, ms, ms * 1000.0 / N, ok);
    return 0;
}

