// Is v inside the half-plane left of directed clip edge (ca -> cb)?
// Filtered: the fast double branch returns the EXACT sign of
// orientation(ca, cb, true_v) whenever |det| exceeds a bound that dominates
// both the double round-off of the determinant AND the ~ulp rounding of the
// stored position; otherwise it escalates to an exact predicate on the
// vertex's exact (depth-1) position.  So the inside/outside decision — which
// drives every topological choice — is mathematically exact.
//
// The exact escalation is split by vertex kind for speed:
//   * Original vertex: its stored (x, y) IS its exact position, so Epick's
//     adaptive-exact orientation (a Shewchuk filtered predicate, ~0.1us, no
//     heap) gives the exact sign directly.
//   * Clip crossing: its stored (x, y) is rounded, so the exact position is
//     the meet of two ORIGINAL lines, evaluated in Epeck (depth-1, exact).
//     This is the only path that touches the lazy exact kernel, and it fires
//     only for the rare crossing that lands within round-off of a later edge.
inline bool inside(double cax, double cay, double cbx, double cby,
                   const Vtx& v) {
    const double ux = cbx - cax, uy = cby - cay;
    const double vx = v.x - cax, vy = v.y - cay;
    const double t1 = ux * vy;
    const double t2 = uy * vx;
    const double det = t1 - t2;
    constexpr double eps = std::numeric_limits<double>::epsilon();
    const double err = 64.0 * eps * (std::abs(t1) + std::abs(t2));
    ++g_ctr.inside_calls;
    if (det >  err) return true;   // strictly left  -> inside
    if (det < -err) return false;  // strictly right -> outside
    ++g_ctr.fallbacks;
    if (v.is_orig) {
        return CGAL::orientation(Point(cax, cay), Point(cbx, cby),
                                 Point(v.x, v.y)) != CGAL::RIGHT_TURN;
    }
    ++g_ctr.meets;
    return CGAL::orientation(to_exact_xy(cax, cay), to_exact_xy(cbx, cby),
                             exact_pos(v)) != CGAL::RIGHT_TURN;
}

// Clip `subject` (CCW) against the half-plane left of directed clip edge
// (ca -> cb), given as ORIGINAL points.
inline std::vector<Vtx> clip_halfplane(const std::vector<Vtx>& subject,
                                       double cax, double cay,
                                       double cbx, double cby) {
    const int n = (int)subject.size();
    std::vector<Vtx> out;
    if (n == 0) return out;
    out.reserve(n + 1);
    const Seg clip_seg{cax, cay, cbx, cby};

    // Carry prev_in across iterations instead of recomputing it: each vertex is
    // classified exactly once per clip edge.
    bool prev_in = inside(cax, cay, cbx, cby, subject[n - 1]);
    for (int i = 0; i < n; ++i) {
        const Vtx& prev = subject[(i - 1 + n) % n];
        const Vtx& cur  = subject[i];
        const bool cur_in = inside(cax, cay, cbx, cby, cur);

        if (cur_in) {
            if (!prev_in) {
                // Entering across the clip line on edge prev->cur (support
                // prev.os).  Entry vertex continues along that subject edge.
                double qx, qy;
                if (dmeet(clip_seg, prev.os, qx, qy))
                    out.push_back(Vtx{qx, qy, prev.os, clip_seg, prev.os, false});
            }
            out.push_back(cur);
        } else if (prev_in) {
            // Leaving on edge prev->cur; exit vertex's outgoing edge runs along
            // the clip line.
            double qx, qy;
            if (dmeet(clip_seg, prev.os, qx, qy))
                out.push_back(Vtx{qx, qy, clip_seg, clip_seg, prev.os, false});
        }
        prev_in = cur_in;
    }
    return out;
}

