// speedup, not an approximation.
inline bool all_points_in_convex_poly_filtered(const std::vector<Point>& inner,
                                               const std::vector<Point>& outer) {
    const int m = static_cast<int>(outer.size());
    if (m < 3) return false;

    // Cache outer vertices as doubles once (outer is small: ~4-8 verts).
    std::array<double, 16> ox, oy;
    const bool use_cache = (m <= 16);
    if (use_cache) {
        for (int j = 0; j < m; ++j) {
            ox[j] = CGAL::to_double(outer[j].x());
            oy[j] = CGAL::to_double(outer[j].y());
        }
    }

    constexpr double C = 8.0 * std::numeric_limits<double>::epsilon();
    for (const auto& v : inner) {
        const double px = CGAL::to_double(v.x());
        const double py = CGAL::to_double(v.y());
        for (int j = 0; j < m; ++j) {
            const int k = (j + 1 == m) ? 0 : j + 1;
            const double ax = use_cache ? ox[j] : CGAL::to_double(outer[j].x());
            const double ay = use_cache ? oy[j] : CGAL::to_double(outer[j].y());
            const double bx = use_cache ? ox[k] : CGAL::to_double(outer[k].x());
            const double by = use_cache ? oy[k] : CGAL::to_double(outer[k].y());
            const double abx = bx - ax, aby = by - ay;
            const double apx = px - ax, apy = py - ay;
            const double t1 = abx * apy, t2 = aby * apx;
            const double det = t1 - t2;
            const double err = C * (std::abs(t1) + std::abs(t2));
