}

// Exact O(log n) point-in-convex-polygon for a CCW polygon.  Uses the same
// CGAL::orientation predicate as the linear scan, so it decides "inside or on
// boundary" (i.e. not a strict RIGHT_TURN) identically; it just evaluates the
// predicate O(log n) times instead of O(n) by binary-searching the vertex fan
// anchored at poly[0].  Requires n >= 3 and CCW orientation.
inline bool point_in_convex_poly_log(const Point& p, const std::vector<Point>& poly) {
