// --- Tolerance-aware orientation for INEXACTLY-constructed points ----------
// O'Rourke emits intersection vertices via Epick line-line constructions, so a
// vertex that lies mathematically ON an input edge can land a few ULPs to
// either side.  Exact-sign predicates (CGAL::orientation) then misclassify it,
// which made the convexity and containment guards reject the vast majority of
// genuinely-valid intersections.  Here we classify a turn as flat whenever
// |cross| sits inside a relative band of the operand magnitudes; the band
// (REL) is many orders of magnitude above the ~1e-7 construction noise at these
// coordinate scales yet far below any real geometric feature, so gross errors
// are still caught.
inline int tol_turn_sign(const Point& a, const Point& b, const Point& c) {
    const double abx = CGAL::to_double(b.x()) - CGAL::to_double(a.x());
    const double aby = CGAL::to_double(b.y()) - CGAL::to_double(a.y());
    const double acx = CGAL::to_double(c.x()) - CGAL::to_double(a.x());
    const double acy = CGAL::to_double(c.y()) - CGAL::to_double(a.y());
    const double cross = abx * acy - aby * acx;
    constexpr double REL = 1e-9;
    const double band = REL * (std::abs(abx * acy) + std::abs(aby * acx));
    if (cross >  band) return  1;   // left turn
    if (cross < -band) return -1;   // right turn
    return 0;                       // (near-)collinear
}

// Point-in-CCW-convex-polygon with the same flatness band: a point counts as
// outside only when it is CLEARLY to the right of some edge, so a constructed
// vertex resting on the boundary is accepted.
inline bool point_in_convex_poly_tol(const Point& p,
                                      const std::vector<Point>& poly) {
    const int n = (int)poly.size();
    for (int i = 0; i < n; ++i) {
        if (tol_turn_sign(poly[i], poly[(i + 1) % n], p) < 0) return false;
    }
    return true;
}

inline bool all_points_in_convex_poly_tol(const std::vector<Point>& inner,
                                          const std::vector<Point>& outer) {
    for (const auto& v : inner) {
        if (!point_in_convex_poly_tol(v, outer)) return false;
    }
    return true;
}

