import sys, math

def read_case(path):
    secs = {}
    cur = None
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split()
            if parts[0] in ('F', 'Gi', 'RAW', 'EXACT'):
                cur = parts[0]
                secs[cur] = []
            else:
                secs[cur].append((float(parts[0]), float(parts[1])))
    return secs

def signed_area(poly):
    s = 0.0
    n = len(poly)
    for i in range(n):
        ax, ay = poly[i]
        bx, by = poly[(i+1)%n]
        s += ax*by - bx*ay
    return s/2

def worst_violation(pts, poly, name):
    # returns (worst_perp, vertex_idx, edge_idx)
    n = len(poly)
    worst = 0.0
    info = None
    for pi, (px, py) in enumerate(pts):
        for e in range(n):
            ax, ay = poly[e]
            bx, by = poly[(e+1)%n]
            ex, ey = bx-ax, by-ay
            L = math.hypot(ex, ey)
            if L < 1e-30:
                continue
            perp = (ex*(py-ay) - ey*(px-ax))/L
            if perp < worst:
                worst = perp
                info = (pi, e, (px,py), (ax,ay),(bx,by))
    return worst, info

for path in sys.argv[1:]:
    print("="*70)
    print(path)
    s = read_case(path)
    for k in ('F','Gi'):
        print(f"  {k}: n={len(s[k])} signed_area={signed_area(s[k]):.3f} "
              f"({'CCW' if signed_area(s[k])>0 else 'CW'})")
    for tag in ('RAW','EXACT'):
        for poly_name in ('F','Gi'):
            w, info = worst_violation(s[tag], s[poly_name], poly_name)
            if info and w < -0.01:
                pi,e,p,a,b = info
                print(f"  {tag} vs {poly_name}: worst={w:.4f} "
                      f"vtx#{pi}={p} vs edge#{e} {a}->{b}")
            else:
                print(f"  {tag} vs {poly_name}: worst={w:.2e} (clean)")

