                             const std::vector<Point>& B) -> double {
    double worst = 0.0;
    for (const auto& a : A) {
        double best = 1e300;
        for (const auto& b : B) {
            double dx = CGAL::to_double(a.x()) - CGAL::to_double(b.x());
            double dy = CGAL::to_double(a.y()) - CGAL::to_double(b.y());
