inline std::vector<int> find_tangent_idx(const Point& p, const std::vector<Point>& S) {
    std::vector<int> tangent;
    tangent.reserve(2);
    const int n = static_cast<int>(S.size());

    // The stab chain S can carry near-coincident consecutive vertices (edges a
    // few ULPs long, accumulated across intersection steps).  The neighbour
    // test needs a genuine adjacent EDGE DIRECTION, so we step over any
    // neighbour within this distance of S[i]; the exact orientation of two
    // ~1e-13-apart points is geometrically meaningless and would misclassify
    // the tangent.  1e-9 is far above the duplicate noise and far below real
    // edge lengths (>=1 unit).
    constexpr double COINCIDENT2 = 1e-18;
    auto coincident = [](const Point& a, const Point& b) {
        const double dx = CGAL::to_double(a.x()) - CGAL::to_double(b.x());
        const double dy = CGAL::to_double(a.y()) - CGAL::to_double(b.y());
        return dx * dx + dy * dy <= COINCIDENT2;
    };

    for (int i = 0; i < n; ++i) {
        int pi = (i + n - 1) % n;
        int steps = 0;
        while (steps < n && coincident(S[pi], S[i])) { pi = (pi + n - 1) % n; ++steps; }
        int ni = (i + 1) % n;
        steps = 0;
        while (steps < n && coincident(S[ni], S[i])) { ni = (ni + 1) % n; ++steps; }

        const CGAL::Orientation op = CGAL::orientation(p, S[i], S[pi]);
        const CGAL::Orientation on = CGAL::orientation(p, S[i], S[ni]);
        const bool penetrates =
            (op == CGAL::LEFT_TURN  && on == CGAL::RIGHT_TURN) ||
            (op == CGAL::RIGHT_TURN && on == CGAL::LEFT_TURN);
        if (!penetrates) tangent.push_back(i);
    }

    if (tangent.size() != 2) tangent.clear();
    return tangent;
}

