#include "simplify_geometry.h"
#include <iostream>
#include <iomanip>

int main() {
    std::vector<Point> P = {
        {3519.4757205267147, -1634.9861111676689},
        {3598.6118445631, -1373.3341682752141},
        {3602.424609743729, -1360.7278215599547},
        {3602.424609743729, -1345.2918201504456},
        {3586.3015055628584, -1313.0456117887045},
        {3511.7377360634559, -1510.0863511973428},
        {3451.6378838304768, -1668.9050295157876},
        {185.09746377403087, -10301},
        {898.45658179417842, -10301},
    };
    std::vector<Point> Q = {
        {3037.0321739918609, -1487.2991547824947},
        {3072.3875130511883, -1558.0098329011496},
        {3107.7428521105157, -1628.7205110198042},
        {3249.164208347825, -1699.4311891384591},
        {3390.5855645851348, -1699.4311891384591},
        {3532.006920822444, -1628.7205110198042},
        {3567.3622598817715, -1558.0098329011496},
        {3602.7175989410989, -1487.2991547824947},
        {3602.7175989410989, -1345.8777985451854},
        {3567.3622598817715, -1275.1671204265306},
        {3532.006920822444, -1204.4564423078759},
        {3390.5855645851348, -1133.7457641892211},
        {3249.164208347825, -1133.7457641892211},
        {3107.7428521105157, -1204.4564423078759},
        {3072.3875130511883, -1275.1671204265306},
        {3037.0321739918609, -1345.8777985451854},
    };

    auto Pd = orourke_cgal::dedup_consecutive(P);
    auto Qd = orourke_cgal::dedup_consecutive(Q);
    std::cout << std::setprecision(15);

    // O'Rourke fast (Epick)
    auto orr = orourke_cgal::convex_intersect_robust(Pd, Qd);
    std::cout << "=== O'Rourke result (" << orr.size() << ") ===\n";
    for (auto& p : orr) std::cout << "  " << CGAL::to_double(p.x()) << " " << CGAL::to_double(p.y()) << "\n";

    // Exact (Epeck Sutherland-Hodgman)
    std::vector<Point> ex;
    intersect_exact_convex(Pd, Qd, ex);
    std::cout << "=== Exact result (" << ex.size() << ") ===\n";
    for (auto& p : ex) std::cout << "  " << CGAL::to_double(p.x()) << " " << CGAL::to_double(p.y()) << "\n";

    // For each O'Rourke vertex, worst signed perp distance outside P and Q
    auto worst_out = [](const std::vector<Point>& pts, const std::vector<Point>& poly, const char* tag){
        const int mm=(int)poly.size();
        for (auto& p : pts) {
            double px=CGAL::to_double(p.x()), py=CGAL::to_double(p.y());
            double worst=0; int we=-1;
            for (int e=0;e<mm;++e){
                double ax=CGAL::to_double(poly[e].x()),ay=CGAL::to_double(poly[e].y());
                double bx=CGAL::to_double(poly[(e+1)%mm].x()),by=CGAL::to_double(poly[(e+1)%mm].y());
                double ex_=bx-ax,ey=by-ay; double len=std::sqrt(ex_*ex_+ey*ey);
                if(len<1e-6) continue;
                double perp=(ex_*(py-ay)-ey*(px-ax))/len;
                if(perp<worst){worst=perp;we=e;}
            }
            if (worst < -1e-6)
                std::cout << "  "<<tag<<" pt("<<px<<","<<py<<") outside by "<<-worst<<" at edge "<<we<<"\n";
        }
    };
    std::cout << "=== O'Rourke vertices outside P ===\n"; worst_out(orr, Pd, "P");
    std::cout << "=== O'Rourke vertices outside Q ===\n"; worst_out(orr, Qd, "Q");
