// Ground truth via CGAL Boolean set operations on EPECK polygons.
static std::vector<Point> cgal_truth(const std::vector<Point>& A,
                                     const std::vector<Point>& B) {
    using EPoint = Epeck::Point_2;
    using EPoly  = CGAL::Polygon_2<Epeck>;
    auto build = [](const std::vector<Point>& v) {
        EPoly poly;
        for (const auto& p : v) poly.push_back(conv_to_exact(p));
        if (poly.orientation() == CGAL::CLOCKWISE) poly.reverse_orientation();
        return poly;
    };
    EPoly pa = build(A), pb = build(B);
    std::vector<CGAL::Polygon_with_holes_2<Epeck>> res;
    CGAL::intersection(pa, pb, std::back_inserter(res));
    std::vector<Point> out;
    if (!res.empty()) {
        const auto& ob = res.front().outer_boundary();
        for (auto it = ob.vertices_begin(); it != ob.vertices_end(); ++it)
            out.emplace_back(CGAL::to_double(it->x()), CGAL::to_double(it->y()));
    }
    return out;
}

