    dump("\n=== Exact Sutherland-Hodgman (fallback) ===", sh);

    // 3. CGAL Boolean ground truth.
    auto truth = cgal_truth(P_verts, Q_verts);
    dump("\n=== CGAL Boolean ground truth ===", truth);

    return 0;
}

