// Worst signed outside-distance of pts vs a CCW convex polygon (negative = out).
static double worst_out(const std::vector<Point>& pts,
                        const std::vector<Point>& poly) {
    double worst = 0.0;
    const int mm = (int)poly.size();
    for (const auto& p : pts) {
        const double px = CGAL::to_double(p.x()), py = CGAL::to_double(p.y());
        for (int e = 0; e < mm; ++e) {
            const double axx = CGAL::to_double(poly[e].x()), ayy = CGAL::to_double(poly[e].y());
            const double bxx = CGAL::to_double(poly[(e+1)%mm].x()), byy = CGAL::to_double(poly[(e+1)%mm].y());
            const double exx = bxx-axx, eyy = byy-ayy;
            const double len = std::sqrt(exx*exx+eyy*eyy);
            if (len < 1e-6) continue;
            const double perp = (exx*(py-ayy) - eyy*(px-axx)) / len;
            if (perp < worst) worst = perp;
        }
    }
    return worst;
}

