// Signed perpendicular distance a point sits OUTSIDE a CCW convex polygon
// (0 if inside). Uses plain doubles; enough for a divergence report.
static double worst_outside(const std::vector<Point>& pts,
                            const std::vector<Point>& poly) {
    double worst = 0.0;
    const int m = (int)poly.size();
    for (const auto& p : pts) {
        const double px = CGAL::to_double(p.x()), py = CGAL::to_double(p.y());
        double this_pt = -1e300;   // most-inside edge governs containment
        for (int e = 0; e < m; ++e) {
            const double ax = CGAL::to_double(poly[e].x()), ay = CGAL::to_double(poly[e].y());
            const double bx = CGAL::to_double(poly[(e+1)%m].x()), by = CGAL::to_double(poly[(e+1)%m].y());
            const double ex = bx-ax, ey = by-ay;
            const double len = std::sqrt(ex*ex+ey*ey);
            if (len < 1e-9) continue;
            const double perp = (ex*(py-ay) - ey*(px-ax)) / len;  // >0 left/inside for CCW
            if (-perp > this_pt) this_pt = -perp;   // outside distance for this edge
        }
        if (this_pt > worst) worst = this_pt;
    }
    return worst;
}

