// clearly-separated majority.
auto orient = [&](int i, int j) -> int {
    const double ux = CGAL::to_double(S[i].x()) - CGAL::to_double(p.x());
    const double uy = CGAL::to_double(S[i].y()) - CGAL::to_double(p.y());
    const double wx = CGAL::to_double(S[j].x()) - CGAL::to_double(p.x());
    const double wy = CGAL::to_double(S[j].y()) - CGAL::to_double(p.y());
    const double t1 = ux * wy, t2 = uy * wx;
    const double det = t1 - t2;
    const double bound = 8.0 * std::numeric_limits<double>::epsilon() *
                         (std::abs(t1) + std::abs(t2));
    if (det >  bound) return  1;
    if (det < -bound) return -1;
    switch (CGAL::orientation(p, S[i], S[j])) {
        case CGAL::LEFT_TURN:  return  1;
        case CGAL::RIGHT_TURN: return -1;
        default:               return  0;
    }
};

