inline bool intersect_orourke_UNUSED(const std::vector<Point>& P_in,
                      const std::vector<Point>& Q_in,
                      std::vector<Point>& result) {
    const std::vector<Point> P_verts = orourke_cgal::dedup_consecutive(P_in);
    const std::vector<Point> Q_verts = orourke_cgal::dedup_consecutive(Q_in);

    result = orourke_cgal::convex_intersect_robust(P_verts, Q_verts);
    if (!result.empty() && result.front() == result.back()) result.pop_back();

    if (result.size() < 3) {
        result.clear();
        return false;
    }

    // Convexity test in O(k): every consecutive turn must share one sign.
    // For O'Rourke output (a bounded intersection of two convex polygons with
    // at most n+m vertices) a consistently-oriented polygon has total turning
    // of exactly 2*pi, hence is simple; so this replaces CGAL's much costlier
    // is_simple()/is_convex()/Polygon construction without weakening the check.
    //
    // The turn sign is computed with a flatness band (tol_turn_sign) because
    // O'Rourke's vertices are Epick line-line constructions: a vertex lying
    // mathematically on an input edge can round to either side, and an
    // exact-sign predicate would then read a real edge as a spurious kink and
    // discard a valid intersection.
    const int k = static_cast<int>(result.size());
    int turn_sign = 0;
    bool unreliable = false;
    for (int i = 0; i < k; ++i) {
        const int s = orourke_cgal::tol_turn_sign(
            result[i], result[(i + 1) % k], result[(i + 2) % k]);
        if (s == 0) continue;
        if (turn_sign == 0) {
            turn_sign = s;
        } else if (turn_sign != s) {
            unreliable = true;  // O'Rourke emitted a kink -> not trustworthy
            break;
        }
    }
    if (turn_sign == 0) unreliable = true;
#ifdef PROFILE_INTERSECT
    extern long g_conv_trip; if (unreliable) g_conv_trip++;
#endif

    // A vertex clearly outside either input means the fast double-precision
    // construction diverged from the true intersection; recompute exactly.
    if (!unreliable &&
        (!orourke_cgal::all_points_in_convex_poly_tol(result, P_verts) ||
         !orourke_cgal::all_points_in_convex_poly_tol(result, Q_verts))) {
        unreliable = true;
#ifdef PROFILE_INTERSECT
        extern long g_cont_trip; g_cont_trip++;
#endif
    }

    if (unreliable) {
#ifdef PROFILE_INTERSECT
        g_fallback_calls++;
        // Measure the true worst perpendicular distance (length-normalized,
        // skipping degenerate edges) of the O'Rourke result outside P and Q.
        // Genuine ill-conditioned failures poke far out; guard false-positives
        // sit within construction noise.  This tells us the split threshold.
        {
            auto worst_out = [](const std::vector<Point>& pts,
                                const std::vector<Point>& poly) -> double {
                double worst = 0.0;
                const int mm = (int)poly.size();
                for (const auto& p : pts) {
                    const double px = CGAL::to_double(p.x()), py = CGAL::to_double(p.y());
                    for (int e = 0; e < mm; ++e) {
                        const double axx = CGAL::to_double(poly[e].x()), ayy = CGAL::to_double(poly[e].y());
                        const double bxx = CGAL::to_double(poly[(e+1)%mm].x()), byy = CGAL::to_double(poly[(e+1)%mm].y());
                        const double exx = bxx-axx, eyy = byy-ayy;
                        const double len = std::sqrt(exx*exx+eyy*eyy);
                        if (len < 1e-6) continue;
                        const double perp = (exx*(py-ayy) - eyy*(px-axx)) / len;
                        if (perp < worst) worst = perp;
                    }
                }
                return worst;
            };
            const double w = std::min(worst_out(result, P_verts),
                                      worst_out(result, Q_verts));
            extern void record_fallback_dist(double);
            record_fallback_dist(-w);  // report as positive outside-distance
#ifdef DUMP_WORST
            // Persist the single worst-diverging (P,Q) pair for offline repro.
            extern void record_worst_pair(double,
                                          const std::vector<Point>&,
                                          const std::vector<Point>&);
            record_worst_pair(-w, P_verts, Q_verts);
#endif
        }
#endif
#ifndef DISABLE_FALLBACK
        return intersect_exact_convex(P_verts, Q_verts, result);
#endif
    }

    if (turn_sign < 0) std::reverse(result.begin(), result.end());
    return true;
}

